import { Actions } from './ActionManager.js';

export function requireBase64Image(url) {
  let urlRe = /^data:image\/(png|jpeg|gif);base64,[a-zA-Z0-9+\/=]+$/;
  if (urlRe.test(url)) {
    return url;
  } else {
    return '';
  }
}
export class PropTemplate {
  constructor(id, width, height, spots, isFloorProp) {
    this.id = id;
    this.width = width;
    this.height = height;
    this.spots = spots;
    this.isFloorProp = isFloorProp;
    this.container = document.createElement('div');
    this.container.classList.add('prop');
  }

  create() {
    return this.container.cloneNode(true);
  }

  static deserialize(prop) {
    let { id, width, height, isFloorProp } = prop;
    let spots = prop.spots.map(spot => new Spot(spot.x, spot.y, spot.allowedActions));
    let image = document.createElement('img');
    image.draggable = false;
    image.style.width = width + 'px';
    image.style.height = height + 'px';
    image.src = requireBase64Image(prop.src);
    let template = new PropTemplate(id, width, height, spots, isFloorProp);
    template.container.appendChild(image);
    return template;
  }

  serialize() {
    let { width, height, isFloorProp } = this;
    let spots = this.spots.map(spot => {
      return {
        x: spot.x,
        y: spot.y,
        allowedActions: spot.allowedActions,
      };
    });

    let src = 'unknown';
    let image = this.container.querySelector('img');
    if (image) {
      src = image.src;

    }
    return {
      width,
      height,
      isFloorProp,
      spots,
      src
    };
  }

  addSpotMarkers() {
    for (let spot of this.spots) {
      let elt = document.createElement('div');
      elt.classList.add('spot-marker');
      elt.style.top = spot.y + 'px';
      elt.style.left = spot.x + 'px';
      this.container.appendChild(elt);
    }
  }

  removeSpotMarkers() {
    Array.from(this.container.querySelectorAll('.spot-marker')).forEach(elt => {
      this.container.removeChild(elt);
    });
  }
}

class Spot {
  constructor(x, y, allowedActions) {
    this.x = x;
    this.y = y;
    this.allowedActions = allowedActions;
    this.occupied = false;
  }

  clone() {
    return new Spot(this.x, this.y, this.allowedActions);
  }
}

